const segs = $input.all().map(i => i.json).filter(s => s.id);
const vistas = {};
const out = [];
segs.forEach(function (s) { if (s.matricula && !vistas[s.matricula]) { vistas[s.matricula] = true; out.push({ json: { matricula: s.matricula } }); } });
return out;

const ahora = Date.now();
const segs = $('Seguimientos activos').all().map(i => i.json).filter(s => s.id);
const mats = $('Matriculas').all().map(i => i.json.matricula);
const resp = $('Consultar matricula').all();
const api = {};
resp.forEach(function (it, idx) {
  const pi = it.pairedItem;
  const k = (pi && typeof pi.item === 'number') ? pi.item : (Array.isArray(pi) && pi[0] ? pi[0].item : idx);
  api[mats[k]] = it.json || {};
});
const todos = $('Cargar textos').all().map(i => i.json);
function tmap(lang) { const t = {}; todos.filter(r => r.idioma === 'es').forEach(r => { t[r.clave] = r.texto; }); todos.filter(r => r.idioma === lang).forEach(r => { t[r.clave] = r.texto; }); return t; }
function esc(s) { return String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function fill(s, o) { return String(s || '').replace(/\{(\w+)\}/g, function (m, k) { return (o[k] !== undefined && o[k] !== null) ? o[k] : ''; }); }
function minutosDe(s) { const m = String(s || '').match(/^(?:(\d+)d )?(\d+):(\d+)/); if (!m) return null; return (m[1] ? Number(m[1]) * 1440 : 0) + Number(m[2]) * 60 + Number(m[3]); }
function ht(s) { const m = String(s || '').match(/^(?:(\d+)d )?(\d+):(\d+)/); if (!m) return String(s || '-'); return (m[1] ? m[1] + ' d ' : '') + Number(m[2]) + ' h ' + m[3] + ' min'; }
function mapa(lat, lon) { if (!lat || !lon || Number(lat) === 0 || Number(lon) === 0) return null; return 'https://www.google.com/maps?q=' + Number(lat) + ',' + Number(lon); }
function distKm(lat1, lon1, lat2, lon2) { const R = 6371; const r = function (x) { return x * Math.PI / 180; }; const dLat = r(lat2 - lat1); const dLon = r(lon2 - lon1); const a = Math.pow(Math.sin(dLat / 2), 2) + Math.cos(r(lat1)) * Math.cos(r(lat2)) * Math.pow(Math.sin(dLon / 2), 2); return 2 * R * Math.asin(Math.sqrt(a)); }
const out = [];
segs.forEach(function (s) {
  const t = tmap(s.idioma || 'es');
  const body = api[s.matricula];
  let estado = 'activo';
  let motivo = '';
  let llegando = !!s.avisado_llegando;
  let parado = !!s.avisado_parado;
  let sinSenal = !!s.avisado_sin_senal;
  let oculta = !!s.aviso_oculta;
  let paradoDesde = Number(s.parado_desde_ms) || 0;
  let ultimaPos = s.ultima_pos || '';
  let ultimaF = s.ultima_pos_f || '';
  const msgs = [];
  function msg(clave, datos, conBoton) { msgs.push({ text: fill(t[clave], datos), conBoton: conBoton }); }
  const base = { matricula: esc(s.matricula) };
  const empresa = esc(s.parada_empresa || '');
  if (Number(s.hasta_ms) <= ahora) {
    estado = 'terminado'; motivo = 'tiempo'; msg('ag_seg_fin_tiempo', base, false);
  } else if (!body) {
  } else if (body.error || (!body.Movimiento && body.message)) {
  } else if (!body.Movimiento) {
    estado = 'terminado'; motivo = 'movimiento'; msg('ag_seg_fin_mov', base, false);
  } else {
    const par = body.cargas_descargas || [];
    const reg = body.pos_act && body.pos_act.Reg;
    const c = reg && reg.loc ? String(reg.loc).split(',') : null;
    const mp = c ? mapa(c[0], c[1]) : null;
    const vel = reg ? Number(reg.veloc) : NaN;
    let objetivo = null;
    let destLat = Number(s.parada_lat) || 0;
    let destLon = Number(s.parada_lon) || 0;
    if (s.modo === 'parada') {
      objetivo = par.find(function (p) { return (String(p.Codigo || p.Empresa) + '|' + String(p.Orden)) === s.parada_codigo; });
      if (objetivo && (!destLat || !destLon)) { destLat = Number(objetivo.Latitud) || 0; destLon = Number(objetivo.Longitud) || 0; }
    }
    const tLat = c ? Number(c[0]) : NaN;
    const tLon = c ? Number(c[1]) : NaN;
    const dist = (s.modo === 'parada' && destLat && destLon && isFinite(tLat) && isFinite(tLon)) ? distKm(tLat, tLon, destLat, destLon) : null;
    if (s.modo === 'parada') {
      if (dist !== null && dist <= 0.3 && (!isFinite(vel) || vel <= 5)) {
        estado = 'terminado'; motivo = 'llegada'; msg('ag_seg_llego', Object.assign({}, base, { empresa: empresa }), false);
      } else if (!objetivo) {
        if (dist !== null) {
          if (!oculta) { oculta = true; msg('ag_seg_parada_oculta', Object.assign({}, base, { empresa: empresa }), true); }
        } else {
          estado = 'terminado'; motivo = 'parada_no_pendiente'; msg('ag_seg_parada_ya_no', Object.assign({}, base, { empresa: empresa }), false);
        }
      }
    }
    if (estado === 'activo') {
      if (s.modo === 'parada' && !llegando) {
        let kms = null;
        let tiempo = '-';
        if (objetivo && objetivo.kms !== undefined) {
          const mins = minutosDe(objetivo.tiempo);
          if (Number(objetivo.kms) <= 15 || (mins !== null && mins <= 30)) { kms = objetivo.kms; tiempo = ht(objetivo.tiempo); }
        } else if (dist !== null && dist <= 15) {
          kms = Math.round(dist * 10) / 10;
        }
        if (kms !== null) {
          llegando = true;
          msg('ag_seg_llegando', Object.assign({}, base, { empresa: empresa || esc(objetivo ? objetivo.Empresa : ''), tiempo: tiempo, kms: kms, mapa: mp || '-' }), true);
        }
      }
      if (reg) {
        ultimaPos = reg.loc || ultimaPos;
        ultimaF = reg.f || ultimaF;
        const f = reg.f ? DateTime.fromFormat(String(reg.f), 'dd/MM/yyyy HH:mm:ss', { zone: $now.zoneName }) : null;
        const sinDatos = !!(f && f.isValid && (ahora - f.toMillis()) >= 30 * 60000);
        if (sinDatos) {
          if (!sinSenal) { sinSenal = true; msg('ag_seg_sin_senal', Object.assign({}, base, { fecha: esc(reg.f), mapa: mp || '-' }), true); }
        } else {
          if (vel === 0) {
            if (!paradoDesde) { paradoDesde = ahora; }
            const cerca = (par.length && par[0].kms !== undefined && Number(par[0].kms) <= 1) || (dist !== null && dist <= 1);
            if (!parado && !cerca && (ahora - paradoDesde) >= 30 * 60000) {
              parado = true;
              msg('ag_seg_parada_larga', Object.assign({}, base, { min: Math.round((ahora - paradoDesde) / 60000), mapa: mp || '-' }), true);
            }
          } else if (vel > 0) { paradoDesde = 0; }
        }
      }
    }
  }
  out.push({ json: { tipo: 'update', id: s.id, estado: estado, motivo_fin: motivo, avisado_llegando: llegando, avisado_parado: parado, avisado_sin_senal: sinSenal, aviso_oculta: oculta, parado_desde_ms: paradoDesde, ultima_pos: ultimaPos, ultima_pos_f: ultimaF } });
  msgs.forEach(function (m) { out.push({ json: { tipo: m.conBoton ? 'msg_btn' : 'msg', chat_id: s.chat_agente, text: m.text, btn: t.ag_btn_parar, cb: 'ag_segstop_' + s.id, btn_loc: t.ag_btn_localizar, cb_loc: 'ag_segloc_' + s.id } }); });
});
return out;

